
#![allow(warnings)]
//! s9 bench (not committed): port versus lifted body on Paged memory.
use ddnative_base::{mem::Mem, emit, x86::{self, Cpu, Flags}};
use serde_json::Value;
use std::collections::BTreeMap;

#[derive(Default)]
struct Paged { table: ddnative_base::mem::PageTable }
impl Mem for Paged {
    fn page_table(&self) -> Option<std::ptr::NonNull<ddnative_base::mem::PageTable>> { Some(std::ptr::NonNull::from(&self.table)) }
    fn u8(&self, a: u32) -> u8 {
        let p = self.table.page((a >> 12) as usize);
        assert!(!p.is_null());
        unsafe { ddnative_base::mem::load_at(p.add((a & 4095) as usize), 1) as u8 }
    }
    fn set_u8(&mut self, a: u32, v: u8) {
        let page = (a >> 12) as usize;
        let p = self.table.backed_page(page);
        self.table.set_perm(page, 3);
        unsafe { ddnative_base::mem::store_at(p.add((a & 4095) as usize), 1, v as u32); }
    }
}
fn n(v: &Value) -> u32 { v.as_u64().unwrap() as u32 }
fn pairs(v: &Value) -> Vec<(u32, u8)> { v.as_array().unwrap().iter().map(|p| (n(&p[0]), n(&p[1]) as u8)).collect() }
fn regs(v: &Value) -> [u32; 8] { let r: Vec<u32> = v["regs"].as_array().unwrap().iter().map(n).collect(); r.try_into().unwrap() }

fn bench(path: &str, port: x86::LiftFn, lifted: x86::LiftFn, skip_memcpy_for_port: bool) {
    ddnative_host::install();
    let text = std::fs::read_to_string(path).unwrap();
    let data: Value = serde_json::from_str(&text).unwrap();
    let cases = data["cases"].as_array().unwrap();
    let mut m = Paged::default();
    let mut totals = [0f64; 2];
    let mut calls = 0u64;
    for (which, body) in [lifted, port].into_iter().enumerate() {
        let name = ["lifted", "port"][which];
        let mut elapsed = std::time::Duration::ZERO;
        let mut count = 0u64;
        for round in 0..6 {
            for case in cases.iter().step_by(5) {
                let initial = pairs(&case["initial"]);
                let events: Vec<Value> = case["events"].as_array().unwrap().iter()
                    .filter(|e| !(skip_memcpy_for_port && n(&e["target"]) == 0x12efea0)).cloned().collect();
                let before = regs(&case["before"]);
                let cursor = std::rc::Rc::new(std::cell::RefCell::new(0usize));
                let c2 = cursor.clone();
                let ev: Vec<(Vec<(u32,u8)>, [u32;8])> = events.iter().map(|e| (pairs(&e["after"]["memory"]), regs(&e["after"]))).collect();
                x86::set_ext_calls(Some(Box::new(move |m, c, _target| {
                    let k = *c2.borrow();
                    let (mem, r) = &ev[k];
                    for &(a, b) in mem { m.set_u8(a, b); }
                    c.eax = r[0];
                    c.esp = r[4];
                    *c2.borrow_mut() += 1;
                })));
                for iteration in 0..40 {
                    for &(a, b) in &initial { m.set_u8(a, b); }
                    *cursor.borrow_mut() = 0;
                    let mut c = Cpu::default();
                    [c.eax, c.ecx, c.edx, c.ebx, c.esp, c.ebp, c.esi, c.edi] = before;
                    let t = std::time::Instant::now();
                    body(std::hint::black_box(&mut m), std::hint::black_box(&mut c));
                    let d = t.elapsed();
                    if round > 0 { elapsed += d; count += 1; }
                    std::hint::black_box(c.eax);
                }
            }
        }
        totals[which] = elapsed.as_nanos() as f64 / count as f64;
        eprintln!("{path}: {name} ns/call = {:.1}", totals[which]);
    }
    x86::set_ext_calls(None);
    eprintln!("speedup = {:.2}x", totals[0] / totals[1]);
}

#[test]
#[ignore]
fn bench_upload() {
    bench("E:/ddda-re/notes/native-L184/model_upload_state.json", mtcore::semantic_s9::model_upload_state, lifted::f_00ea5b50, true);
}
#[test]
#[ignore]
fn bench_pop() {
    bench("E:/ddda-re/notes/native-L184/pop_render_state.json", mtcore::semantic_s9::pop_render_state, lifted::f_00fed5d0, true);
}
#[test]
#[ignore]
fn bench_fade() {
    bench("E:/ddda-re/notes/native-L184/set_fade.json", mtcore::semantic_s9::set_fade, lifted::f_00ff1310, true);
}

